    // 4️⃣ Делегированный обработчик кликов (единственный listener)
    const onClick = (e) => {
      if (e.target.id === "login-button") handleSubmit();
      if (e.target.id === "toggle-button") {
        isLoginMode = !isLoginMode;
        imageUrl = "";
        renderForm();
      }
    };
    appEl.addEventListener("click", onClick, { once: true }); // будет удалён при следующем renderForm()
  };

  // --- отправка формы ---------------------------------------------------------
  const handleSubmit = () => {
    clearError();

    if (isLoginMode) {
      const err = validateLogin();
      if (err) return setError(err);
      loginUser({ login: getValue("login-input"), password: getValue("password-input") })
        .then((res) => setUser(res.user))
        .catch((e) => setError(e.message || "Ошибка входа"));
    } else {
      const err = validateRegister();
      if (err) return setError(err);
      registerUser({
        login: getValue("login-input"),
        password: getValue("password-input"),
        name: getValue("name-input"),
        imageUrl,
      })
        .then((res) => setUser(res.user))
        .catch((e) => setError(e.message || "Ошибка регистрации"));
    }
  };

  // --- старт -----------------------------------------------------------------
  renderForm();
}
```

