```js
// src/components/add-post-page-component.js
import { renderHeaderComponent } from "./header-component.js";
import { renderUploadImageComponent } from "./upload-image-component.js";

/**
 * @param {Object} params
 * @param {HTMLElement} params.appEl   – контейнер приложения.
 * @param {Function}    params.onAddPostClick – (post) => void.
 * @param {Object}      [params.labels] – UI‑тексты для i18n.
 */
export function renderAddPostPageComponent({
  appEl,
  onAddPostClick,
  labels = {
    title: "Добавить пост",
    descriptionPlaceholder: "Опишите фотографию",
    addButton: "Добавить",
    noImage: "Пожалуйста, выберите фото",
    noDescription: "Пожалуйста, добавьте описание",
    errorAria: "Сообщения об ошибках",
  },
}) {
  // ---------- состояние ----------
  let imageUrl = "";

  // ---------- утилиты ----------
  const setError = (msg) =>
    (appEl.querySelector(".form-error").textContent = msg);
  const clearError = () => setError("");

  // ---------- шаблон ----------
  const tmpl = document.createElement("template");
  tmpl.innerHTML = `
    <div class="page-container">
      <div class="header-container"></div>
      <form class="form" role="form" aria-labelledby="add-post-title" novalidate>
        <h3 class="form-title" id="add-post-title">${labels.title}</h3>
        <div class="form-inputs">
          <div class="upload-image-container" aria-label="Загрузка изображения"></div>

          <label for="description-input">
            ${labels.descriptionPlaceholder}:
            <textarea id="description-input" class="input textarea"
              rows="4" aria-required="true"></textarea>
          </label>

          <div class="form-error" role="alert" aria-live="assertive"></div>

          <button type="button" class="button" id="add-button">
            ${labels.addButton}
          </button>
        </div>
      </form>
    </div>`;

  // ---------- рендер ----------
  const render = () => {
    // 1️⃣ Очистка и клонирование шаблона
    appEl.innerHTML = "";
    appEl.appendChild(tmpl.content.cloneNode(true));

    // 2️⃣ Header
    renderHeaderComponent({
      element: appEl.querySelector(".header-container"),
    });

    // 3️⃣ Upload‑image
    const uploadContainer = appEl.querySelector(".upload-image-container");
    if (uploadContainer) {
      renderUploadImageComponent({
        element: uploadContainer,
        onImageUrlChange: (url) => (imageUrl = url),
      });
    }

    // 4️⃣ Делегируем клики
    const onClick = (e) => {
      if (e.target.id !== "add-button") return;
      clearError();

      const description = appEl.querySelector("#description-input").value.trim();

      if (!imageUrl) return setError(labels.noImage);
      if (!description) return setError(labels.noDescription);

      // -------------------------------------------------
      try {
        const result = onAddPostClick({ description, imageUrl });
        // Если коллбек возвращает промис, обработаем его
        if (result instanceof Promise) {
          result.catch((err) => setError(err?.message ?? "Ошибка добавления"));
        }
        // Сбросить состояние для следующего поста
        imageUrl = "";
        appEl.querySelector("#description-input").value = "";
      } catch (err) {
        setError(err?.message ?? "Ошибка добавления");
      }
    };

    appEl.addEventListener("click", onClick);
  };

  // ---------- старт ----------
  render();

  // Возврат полезных ссылок (опционально, для тестов)
  return {
    root: appEl,
    descriptionInput: appEl.querySelector("#description-input"),
    addButton: appEl.querySelector("#add-button"),
    uploadContainer: appEl.querySelector(".upload-image-container"),
  };
}
```

