## 🛠 Минимальный рефакторинг (ES‑модуль)

```js
// src/components/post-page-component.js
import { USER_POSTS_PAGE } from "../routes.js";
import { renderHeaderComponent } from "./header-component.js";
import { posts, user, goToPage } from "../index.js";
import { likePost, dislikePost } from "../api.js";
import formatDistanceToNow from
  "https://cdn.jsdelivr.net/npm/date-fns@2.29.3/esm/formatDistanceToNow/index.js";
import ru from
  "https://cdn.jsdelivr.net/npm/date-fns@2.29.3/esm/locale/ru/index.js";

export function renderPostsPageComponent({ appEl, labels = defaultLabels }) {
  // ---------- шаблон ----------
  const tmpl = document.createElement("template");
  tmpl.innerHTML = `
    <div class="page-container">
      <div class="header-container"></div>
      <ul class="posts" role="list"></ul>
    </div>`;

  // ---------- очистка и вставка ----------
  appEl.innerHTML = "";
  appEl.appendChild(tmpl.content.cloneNode(true));

  // ---------- Header ----------
  renderHeaderComponent({
    element: appEl.querySelector(".header-container"),
  });

  // ---------- Посты ----------
  const postsContainer = appEl.querySelector(".posts");
  postsContainer.innerHTML = posts
    .map((post) => {
      const createDate = post.createdAt
        ? formatDistanceToNow(new Date(post.createdAt), {
            addSuffix: true,
            locale: ru,
          })
        : labels.justNow;

      // Экранируем пользовательские строки через createElement
      const li = document.createElement("li");
      li.className = "post";
      li.setAttribute("role", "listitem");

      // Header (клик → профиль)
      const header = document.createElement("div");
      header.className = "post-header";
      header.dataset.userId = post.user.id;
      header.setAttribute("role", "button");
      header.setAttribute("aria-label", `${labels.profileOf} ${post.user.name}`);
      const imgUser = document.createElement("img");
      imgUser.className = "post-header__user-image";
      imgUser.src = post.user.imageUrl;
      imgUser.alt = `${labels.userAvatar} ${post.user.name}`;
      const nameUser = document.createElement("p");
      nameUser.className = "post-header__user-name";
      nameUser.textContent = post.user.name;
      header.append(imgUser, nameUser);
      li.append(header);

      // Image
      const imgWrapper = document.createElement("div");
      imgWrapper.className = "post-image-container";
      const img = document.createElement("img");
      img.className = "post-image";
      img.src = post.imageUrl;
      img.alt = labels.postImageAlt;
      imgWrapper.append(img);
      li.append(imgWrapper);

      // Likes block
      const likesDiv = document.createElement("div");
      likesDiv.className = "post-likes";

      const likeBtn = document.createElement("button");
      likeBtn.className = "like-button";
      likeBtn.dataset.postId = post.id;
      likeBtn.setAttribute("aria-pressed", post.isLiked);
      const likeIcon = document.createElement("img");
      likeIcon.src = `./assets/images/${
        post.isLiked ? "like-active.svg" : "like-not-active.svg"
      }`;
      likeIcon.alt = labels.likeAlt;
      likeBtn.append(likeIcon);
      likesDiv.append(likeBtn);

      const likesText = document.createElement("p");
      likesText.className = "post-likes-text";
      likesText.innerHTML = `${labels.likes}: <strong>${post.likes.length}</strong>`;
      likesDiv.append(likesText);
      li.append(likesDiv);

      // Description
      const desc = document.createElement("p");
      desc.className = "post-text";
      const userSpan = document.createElement("span");
      userSpan.className = "user-name";
      userSpan.textContent = post.user.name;
      desc.append(userSpan, ` ${post.description}`);
      li.append(desc);

      // Date
      const dateP = document.createElement("p");
      dateP.className = "post-date";
      dateP.textContent = createDate;
      li.append(dateP);

      return li.outerHTML;
    })
    .join("");

  // ---------- UI‑сообщения ----------
  const errorBox = document.createElement("div");
  errorBox.className = "post-error";
  errorBox.setAttribute("role", "alert");
  errorBox.setAttribute("aria-live", "assertive");
  appEl.appendChild(errorBox);

  // ---------- Делегирование событий ----------
  const onClick = (e) => {
    // 1️⃣ Клик по лайку
    if (e.target.closest(".like-button")) {
      const btn = e.target.closest(".like-button");
      if (!user) {
        errorBox.textContent = labels.authRequired;
        return;
      }
      const postId = btn.dataset.postId;
      const post = posts.find((p) => p.id === postId);
      const apiFn = post.isLiked ? dislikePost : likePost;

      // optimistic UI
      post.isLiked = !post.isLiked;
      post.likes = post.isLiked
        ? [...post.likes, user.id]
        : post.likes.filter((id) => id !== user.id);
      renderPostsPageComponent({ appEl, labels });

      apiFn({ token: `Bearer ${user.token}`, postId })
        .then((data) => {
          const updated = data.post || data;
          post.likes = updated.likes ?? post.likes;
          post.isLiked = updated.isLiked ?? post.isLiked;
          renderPostsPageComponent({ appEl, labels });
        })
        .catch((err) => {
          console.error("Like error:", err);
          errorBox.textContent = labels.likeError;
          // откатываем optimistic‑изменения
          post.isLiked = !post.isLiked;
          post.likes = post.likes.filter((id) => id !== user.id);
          renderPostsPageComponent({ appEl, labels });
        });
      return;
    }

    // 2️⃣ Клик по заголовку автора
    if (e.target.closest(".post-header")) {
      const hdr = e.target.closest(".post-header");
      goToPage(USER_POSTS_PAGE, { userId: hdr.dataset.userId });
    }
  };

  appEl.addEventListener("click", onClick);

  // ---------- Возврат полезных ссылок (для тестов) ----------
  return {
    root: appEl,
    postsContainer,
    errorBox,
    headerElements: appEl.querySelectorAll(".post-header"),
    likeButtons: appEl.querySelectorAll(".like-button"),
  };
}

/* ----- Локализуемые строки по‑умолчанию ----- */
const defaultLabels = {
  profileOf: "Профиль пользователя",
  userAvatar: "Аватар пользователя",
  postImageAlt: "Картинка поста",
  likeAlt: "Кнопка лайка",
  likes: "Нравится",
  authRequired: "Чтобы поставить лайк, нужна авторизация",
  likeError: "Не удалось обработать лайк.",
  justNow: "только что",
};
```

