// src/components/post-card-component.js
export const renderPostCardComponent = (post) => {
  const li = document.createElement('li');
  li.className = 'post-card';

  const img = document.createElement('img');
  img.src = post.imageUrl || './assets/images/default-post.jpg';
  img.alt = post.description ?? 'Фото пользователя';
  img.loading = 'lazy';

  // Если сервер вернул 404/ошибку → ставим дефолтную картинку
  img.onerror = () => {
    img.onerror = null; // чтобы не зациклить замену
    img.src = './assets/images/default-post.jpg';
  };

  // дальше собираете остальное (description, likes и т.д.)
  li.append(img);
  // …
  return li;
};
